  for (i = 0; i < 3; i++)
    for (j = 0; j < 3; j++) n_f[i][j] = f[i][j];

  for (i = 0; i < 3; i++)
    for (j = 0; j < 3; j++) n_f[i][j] -= screen_point[j];

  for (i = 0; i < 3; i++) {
    xx = n_f[i][0];
    yy = n_f[i][1];
