    n_f[i][0] = xx * coff_matrix[0][0] + yy * coff_matrix[1][0] +
                zz * coff_matrix[2][0];
    n_f[i][1] = xx * coff_matrix[0][1] + yy * coff_matrix[1][1] +
                zz * coff_matrix[2][1];
    n_f[i][2] = xx * coff_matrix[0][2] + yy * coff_matrix[1][2] +
                zz * coff_matrix[2][2];
  }
  return;
}

