void unescape(char s[],char t[])
{
 int i,j;

 for(i=j=0;t[i]!='\0';++i)
  switch(t[i])
  {
   case '\\':
    switch(t[++i])
    {
     case 'n':
      s[j++]='\n';
      break;
     case 't':
      s[j++]='\t';
      break;
     default:
      s[j++]='\\';
      s[j++]=t[i];
      break;
    }
    break;
   default:
    s[j++]=t[i];
    break;
  }
  s[j]='\0';
}

