    for(i = 0; i < 8; i++){
      for(j = 0; j < 8; j++){
 if(i*8 + j == zz_order[h]){

   temp_matrix[i][j] = quant_coefficient_matrix[h/8][h%8];
 }
      }
    }
  }


  for(i = 0; i < 8; i++){
    for(j = 0; j < 8; j++){
      quant_coefficient_matrix[i][j] = temp_matrix[i][j];
    }
  }



}

