void rot13 (char *buf)
{
    int index=0;
    char c=buf[index];

    while (c!=0) {
        if (c<'A' || c>'z' || (c>'Z' && c<'a')) {
            buf[index] = buf[index];
        } else {
            if (c>'m' || (c>'M' && c<'a')) {
         buf[index] = buf[index]-13;
     } else {
         buf[index] = buf[index]+13;
     }
        }
 c=buf[++index];
    }
}

