int itoa(int val, char* buf)
{
    const unsigned int radix = 10;

    char* p;
    unsigned int a;
    int len;
    char* b;
    char temp;
    unsigned int u;

    p = buf;

    if (val < 0)
    {
        *p++ = '-';
        val = 0 - val;
    }
    u = (unsigned int)val;

    b = p;

    do
    {
        a = u % radix;
        u /= radix;

        *p++ = a + '0';

    } while (u > 0);

    len = (int)(p - buf);

    *p-- = 0;


    do
    {
        temp = *p;
        *p = *b;
        *b = temp;
        --p;
        ++b;

